def _digito_cnpj(digitos: str) -> str:
    pesos = list(range(len(digitos) - 7, 1, -1)) + list(range(9, 1, -1))
    resto = sum(int(d) * p for d, p in zip(digitos, pesos, strict=True)) % 11
    return "0" if resto < 2 else str(11 - resto)


def cnpj_da_matriz(cnpj_filial: str) -> str:
    """Mesma raiz da filial, com a ordem 0001 e os dígitos recalculados."""
    base = "".join(c for c in cnpj_filial if c.isdigit())[:8] + "0001"
    base += _digito_cnpj(base)
    base += _digito_cnpj(base)
    return f"{base[:2]}.{base[2:5]}.{base[5:8]}/{base[8:12]}-{base[12:]}"


def criar_matrizes_e_vincular(apps, schema_editor):  # noqa: ANN001
    """Uma matriz por raiz de CNPJ, com os dados da primeira filial (revisar)."""
    Empresa = apps.get_model("sistema", "Empresa")
    Usuario = apps.get_model("sistema", "Usuario")
    banco = schema_editor.connection.alias
    filiais = Empresa.objects.using(banco).filter(tipo="FILIAL", matriz__isnull=True)
    for filial in filiais.order_by("pk"):
        cnpj = cnpj_da_matriz(filial.cnpj)
        matriz = Empresa.objects.using(banco).filter(cnpj=cnpj).first()
        if matriz is None:
            matriz = Empresa.objects.using(banco).create(
                tipo="MATRIZ",
                cnpj=cnpj,
                usuario_inclusao_id=filial.usuario_inclusao_id,
                **{campo: getattr(filial, campo) for campo in CAMPOS_COPIADOS},
            )
        elif matriz.tipo != "MATRIZ":
            matriz.tipo = "MATRIZ"
            matriz.descricao_filial = ""
            matriz.save(update_fields=["tipo", "descricao_filial"])
        filial.matriz_id = matriz.pk
        filial.save(update_fields=["matriz"])
    for usuario in Usuario.objects.using(banco).exclude(empresa_id=None):
        empresa = Empresa.objects.using(banco).get(pk=usuario.empresa_id)
        usuario.matriz_id = empresa.matriz_id or empresa.pk
        usuario.save(update_fields=["matriz"])
        usuario.empresas.add(empresa)


